import{_ as a,o,c as i,a2 as r}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Space Authorization Model","description":"","frontmatter":{},"headers":[],"relativePath":"space-authorization-model.md","filePath":"space-authorization-model.md","lastUpdated":1780254295000}'),s={name:"space-authorization-model.md"};function t(n,e,l,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="space-authorization-model" tabindex="-1">Space Authorization Model <a class="header-anchor" href="#space-authorization-model" aria-label="Permalink to &quot;Space Authorization Model&quot;">​</a></h1><p>This document defines how Soma authorizes reads and writes of space-scoped content (documents, messages, blobs).</p><h2 id="what-counts-as-a-member" tabindex="-1">What counts as a member? <a class="header-anchor" href="#what-counts-as-a-member" aria-label="Permalink to &quot;What counts as a member?&quot;">​</a></h2><p>Possession of a valid <code>MembershipCapability</code> for the target <code>space_id</code>:</p><ul><li>Signed (<code>signed</code> present).</li><li>Subject matches the requester’s libp2p <code>PeerId</code> from the authenticated channel.</li><li>Not expired (<code>expires_at</code> is in the future, if set).</li><li>Issuer is trusted: <ul><li>Issuer is the space owner, <strong>or</strong></li><li>Issuer presents a valid <code>IssuerCapability</code> delegated by the owner for that space.</li></ul></li></ul><h2 id="invariant-all-space-reads-require-membership" tabindex="-1">Invariant: all space reads require membership <a class="header-anchor" href="#invariant-all-space-reads-require-membership" aria-label="Permalink to &quot;Invariant: all space reads require membership&quot;">​</a></h2><p>Every surface that returns space content must check membership:</p><ul><li>libp2p request/response (<code>/soma/blob/1</code> and any future protocols).</li><li>In-process daemon surface exposed to the renderer via the Tauri host (<code>desktop-api</code> handlers → <code>desktop-commands</code> → <code>@soma/sdk</code>).</li><li><code>somad bot</code> admin HTTP (if it ever exposes read APIs).</li></ul><p>Controllers are thin; the check should live in the service layer so all surfaces reuse it.</p><h2 id="where-membership-is-enforced-today" tabindex="-1">Where membership is enforced today <a class="header-anchor" href="#where-membership-is-enforced-today" aria-label="Permalink to &quot;Where membership is enforced today&quot;">​</a></h2><ul><li>libp2p blobs: blob handler calls <code>SpaceAuthorizer</code> before serving bytes.</li><li>In-process daemon (via the Tauri command surface): <code>uploadBlob</code>/<code>upsertDocument</code> require membership.</li><li>Space creation: <code>CreateSpace</code> stores owner metadata plus an owner-signed <code>SpaceGenesisArtifact</code>.</li><li>Join decisions: membership capabilities are signature/subject/issuer-checked before persistence; delegated issuer chains are verified when the owner key is known.</li><li>Issuer delegation: <code>IssueIssuerCapability</code> is implemented on the in-process daemon surface, requires the current daemon to own the space, and persists the owner-signed delegation locally.</li><li>Discovery: <code>DiscoverSpaces</code> is implemented as local known-space discovery. It does not query rendezvous metadata yet.</li></ul><h2 id="verification-rules" tabindex="-1">Verification rules <a class="header-anchor" href="#verification-rules" aria-label="Permalink to &quot;Verification rules&quot;">​</a></h2><ul><li>Verify signatures with the signer’s libp2p public key (from Identify).</li><li>Bind <code>subject_peer_id</code> to the remote peer identity (not payload).</li><li>Enforce expiry on membership and issuer capabilities.</li><li>Delegation chain: owner signs issuer cap → issuer signs membership cap.</li><li>Reject signed capability payload mismatches so post-signature field tampering does not persist.</li></ul><h2 id="notes-and-gaps" tabindex="-1">Notes and gaps <a class="header-anchor" href="#notes-and-gaps" aria-label="Permalink to &quot;Notes and gaps&quot;">​</a></h2><ul><li>Owner public key discovery is required to validate delegations where owner ≠ sender.</li><li>The signing payload uses the current CBOR view helpers; canonical CBOR remains a cross-version interoperability task.</li><li>UI guardrails should redirect non-members from space routes, but the backend is the security boundary.</li><li>Future work: revocation + key rotation, and optional end-to-end encryption by space.</li></ul><h2 id="terminology-note" tabindex="-1">Terminology note <a class="header-anchor" href="#terminology-note" aria-label="Permalink to &quot;Terminology note&quot;">​</a></h2><ul><li><code>Owner</code>, <code>Editor</code>, <code>Viewer</code>, <code>Member</code>, and <code>Bot</code> are workspace access roles.</li><li>Bot operating mode like <code>admin</code> is deployment/runtime terminology, not a human workspace role.</li><li>Local AI model feature hints in the desktop UI are not security capabilities and do not grant access.</li><li>A delegated approver is a separate authority concept. A bot may be a delegated approver, but the <code>Bot</code> role alone does not imply join approval powers.</li></ul>',17)])])}const m=a(s,[["render",t]]);export{h as __pageData,m as default};
